import { z } from 'zod';

// Property ids are generated by the server (`prp` + 9 chars, see
// common/helpers/nanoid.utils); choice ids come from the client (`opt` + 9).
export const BASE_PROPERTY_ID_RE = /^prp[a-z0-9]{9}$/;
export const basePropertyIdSchema = z
  .string()
  .regex(BASE_PROPERTY_ID_RE, 'Invalid property id');
export const baseChoiceIdSchema = z.string().min(1).max(64);
